package course.domain;

/**
 * Movie from the cinema database, identified by an id of type Long
 * (the id is generated by the database at save)
 */
public class Movie extends Entity<Long> {
    private String title;
    private String director;
    private int year;
    private int durationMinutes;

    /**
     * creates a movie without id; the id is set by the repository at save
     *
     * @param title   - the title of the movie
     * @param director - the director of the movie
     * @param year      - the year of release
     * @param durationMinutes  - the duration, in minutes
     */
    public Movie(String title, String director, int year, int durationMinutes) {
        this.title = title;
        this.director = director;
        this.year = year;
        this.durationMinutes = durationMinutes;
    }

    /**
     *
     * @return the title of the movie
     */
    public String getTitle() {
        return title;
    }

    /**
     *
     * @param title - the new title of the movie
     */
    public void setTitle(String title) {
        this.title = title;
    }

    /**
     *
     * @return the director of the movie
     */
    public String getDirector() {
        return director;
    }

    /**
     *
     * @param director - the new director of the movie
     */
    public void setDirector(String director) {
        this.director = director;
    }

    /**
     *
     * @return the year of release
     */
    public int getYear() {
        return year;
    }

    /**
     *
     * @param year - the new year of release
     */
    public void setYear(int year) {
        this.year = year;
    }

    /**
     *
     * @return the duration, in minutes
     */
    public int getDurationMinutes() {
        return durationMinutes;
    }

    /**
     *
     * @param durationMinutes - the new duration, in minutes
     */
    public void setDurationMinutes(int durationMinutes) {
        this.durationMinutes = durationMinutes;
    }

    /**
     *
     * @return the string representation of the movie
     */
    @Override
    public String toString() {
        return "Movie{id=" + id + ", title='" + title + "', director='" + director
                + "', year=" + year + ", durationMinutes=" + durationMinutes + "}";
    }
}
